const upgradedSignature=signature.map(r=>({...r,tags:r.name==="Air Fryer Chicken Kiev"?["Air Fryer","High Protein"]:r.tags,steps:strongerSteps[r.name]||r.steps}));
function recipeImage(path?:string){return path?`/recipe-images/${path.replace(/^\//,"").replace(/\.[^.]+$/,".webp")}`:undefined}
const recipes:Recipe[]=[...upgradedSignature,...recovered,...additions].map((r,i)=>({...r,id:i+1,image:exactPhotoByName[r.name]||(r.name==="Crispy Chicken Wraps"?"/recipe-images/crispy-chicken-wraps.png":recipeImage(r.image)||imageFor(r))}));
const days=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];
const chefRemarks=["Keep your eyes on it. Dinner will not save itself.","Use the timer, not a hopeful guess.","If it still looks pale, it is not finished.","Give it room in the pan; crowding it is how flavour gets steamed to death.","Taste it before serving. Your tongue is part of the equipment.","Do not start washing up now; the hot pan still has work to do.","A proper sizzle is the point. A sad hiss means turn the heat up.","Keep the heat sensible; panic does not make food cook faster.","Leave it alone for a minute. Constant poking is not a cooking technique.","Get it onto the plate while it is hot, not when the conversation finally stops.","Season with conviction. Timid food is nobody’s reward.","Watch the edges; that is where good food turns into a rescue mission.","Do not drown it. Sauce should coat the food, not give it swimming lessons.","Put the lid on only when the recipe says. Steam is not a personality trait.","Use a clean spoon to taste it. We are cooking, not running a biohazard lab.","Finish it properly; nearly good food is still not good enough."];
function chefStep(recipe:Recipe,step:string,index:number){return `${step} ${chefRemarks[(recipe.id*7+index*3)%chefRemarks.length]}`}
function shoppingIngredient(value:string){const clean=value.replace(/\b(sliced|diced|chopped|minced|grated|melted|drained|halved|crushed|shredded|finely|roughly|cooked|skin-on|bone-in|reduced-fat|fresh)\b/gi,"").replace(/\s*,\s*/g," ").replace(/\s+/g," ").trim();const match=clean.match(/^(\d+(?:\.\d+|[¼½¾])?)\s*(kg|g|ml|l|tbsp|tsp)?\b\s*(.+)$/i);if(!match)return{key:clean.toLowerCase(),name:clean,amount:0,unit:""};const fraction={"¼":.25,"½":.5,"¾":.75}[match[1].slice(-1)]||0;const amount=fraction?Number(match[1].slice(0,-1)||0)+fraction:Number(match[1]);const unit=(match[2]||"").toLowerCase();const name=match[3].replace(/\b(breasts|fillets)\b/gi,"breast").trim();return{key:`${name.toLowerCase()}|${unit}`,name,amount,unit}}
function shoppingLabel(name:string,amount:number,unit:string,count:number){if(amount){const value=Number.isInteger(amount)?amount:String(Number(amount.toFixed(2)));return `${value}${unit?unit+" ":" "}${name}`}return count>1?`${name} ×${count}`:name}
recipes.forEach(recipe=>{recipe.steps=recipe.steps.map((step,index)=>chefStep(recipe,step,index))})
function useSaved<T>(key:string,initial:T){const[value,setValue]=useState<T>(initial);useEffect(()=>{try{const raw=localStorage.getItem(key);if(raw)setValue(JSON.parse(raw))}catch{}},[key]);useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}},[key,value]);return[value,setValue]as const}

export default function Home(){
 const[view,setView]=useState<"recipes"|"fridge"|"planner"|"shopping"|"favourites">("recipes");const[query,setQuery]=useState("");const[cat,setCat]=useState("All");const[sort,setSort]=useState("top");const[selected,setSelected]=useState<Recipe|null>(null);const[servings,setServings]=useState(4);const[favourites,setFavourites]=useSaved<number[]>("grim-faves",[]);const[planner,setPlanner]=useSaved<Record<string,number[]>>("grim-planner",{});const[checked,setChecked]=useSaved<string[]>("grim-checked",[]);const[fridge,setFridge]=useState("");
 const[removed,setRemoved]=useSaved<string[]>("grim-removed-shopping",[]);const[showTop,setShowTop]=useState(false);
 const visible=useMemo(()=>{const words=(view==="fridge"?fridge:query).toLowerCase().split(/[,\s]+/).filter(Boolean);let list=recipes.filter(r=>(cat==="All"||r.category===cat||r.tags.includes(cat))&&(cat!=="Budget"||r.cost<=2.5));if(words.length)list=list.filter(r=>{const haystack=(r.name+" "+r.ingredients.join(" ")).toLowerCase();return view==="fridge"?words.every(w=>haystack.includes(w)):words.some(w=>haystack.includes(w))});return[...list].sort((a,b)=>sort==="cheap"?a.cost-b.cost:sort==="quick"?a.time-b.time:sort==="protein"?b.protein-a.protein:b.score-a.score)},[query,fridge,cat,sort,view]);
 const planned=Object.values(planner).flat().map(id=>recipes.find(r=>r.id===id)).filter(Boolean)as Recipe[];const shopping=useMemo(()=>{const map=new Map<string,{name:string;amount:number;unit:string;count:number}>();planned.forEach(r=>r.ingredients.forEach(raw=>{const item=shoppingIngredient(raw);const old=map.get(item.key);map.set(item.key,old?{...old,amount:old.amount+item.amount,count:old.count+1}:{...item,count:1})}));return[...map.values()].map(item=>[shoppingLabel(item.name,item.amount,item.unit,item.count),item.amount?1:item.count]as[string,number])},[planned]);const visibleShopping=shopping.filter(([item])=>!removed.includes(item));const toggleFav=(id:number)=>setFavourites(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);const addPlan=(day:string,id:number)=>{if((planner[day]||[]).length&&!window.confirm(`${day} already has a meal planned. Add this one as well?`))return false;setPlanner({...planner,[day]:[...(planner[day]||[]),id]});return true};
 useEffect(()=>{window.scrollTo({top:0,behavior:"auto"})},[selected,view]);
 useEffect(()=>{const track=()=>setShowTop(window.scrollY>500);track();window.addEventListener("scroll",track,{passive:true});return()=>window.removeEventListener("scroll",track)},[]);
 useEffect(()=>{const context=(document as Document&{modelContext?:{registerTool:(tool:unknown,options?:{signal:AbortSignal})=>void|Promise<void>}}).modelContext;if(!context?.registerTool)return;const life=new AbortController();void Promise.resolve(context.registerTool({name:"add_meal_to_planner",title:"Add meal to planner",description:"Add a GrimRecipes dish to one day of the visible weekly meal planner.",inputSchema:{type:"object",properties:{recipe:{type:"string"},day:{type:"string",enum:days}},required:["recipe","day"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input:unknown){const data=input as{recipe?:string;day?:string};const found=recipes.find(r=>r.name.toLowerCase()===data.recipe?.toLowerCase());if(!found||!data.day||!days.includes(data.day))throw new Error("Use an exact recipe name and a valid day.");addPlan(data.day,found.id);setView("planner");setSelected(null);return{added:found.name,day:data.day}}},{signal:life.signal})).catch(()=>{});return()=>life.abort()},[setPlanner]);
 return <main><header className="topbar"><button className="brand" onClick={()=>{setView("recipes");setSelected(null)}} aria-label="GrimRecipes home"><img src="/grimrecipes-logo.png" alt="GrimRecipes — Real Food. Bad Attitude."/></button><nav><button className={view==="recipes"?"active":""} onClick={()=>{setView("recipes");setSelected(null)}}><ChefHat/>FEED ME</button><button className={view==="fridge"?"active":""} onClick={()=>{setView("fridge");setSelected(null)}}><Refrigerator/>FRIDGE RAID</button><button className={view==="favourites"?"active":""} onClick={()=>{setView("favourites");setSelected(null)}}><Heart/>FAVOURITES</button><button className={view==="planner"?"active":""} onClick={()=>{setView("planner");setSelected(null)}}><CalendarDays/>WEEK SORTED</button><button className={view==="shopping"?"active":""} onClick={()=>{setView("shopping");setSelected(null)}}><ShoppingBasket/>GET THE STUFF <i>{shopping.length}</i></button></nav></header>
 {selected?<RecipeDetail recipe={selected} servings={servings} setServings={setServings} onBack={()=>setSelected(null)} favourite={favourites.includes(selected.id)} toggleFav={toggleFav} addPlan={addPlan}/>:<>{view==="recipes"&&<><section className="hero"><div className="hero-copy"><span className="eyebrow">REAL FOOD. BAD ATTITUDE.</span><h1>COOK<br/><em>PROPER FOOD.</em></h1><p>You’re hungry. We’ve got food. Let’s skip the childhood memories and cook the bloody thing.</p><label className="search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="What are you shoving in your face?"/><kbd>{visible.length} victims</kbd></label></div><div className="hero-image" role="img" aria-label="Four hearty GrimRecipes dishes"><span>TONIGHT: FOOD, NOT EXCUSES</span></div></section><CategoryBar cat={cat} setCat={setCat}/><section className="catalog"><div className="section-head"><div><span className="eyebrow">WHAT ARE WE COOKING?</span><h2>{cat==="All"?"Choose dinner, genius":cat}</h2></div><div className="catalog-actions"><select value={sort} onChange={e=>setSort(e.target.value)}><option value="top">Least disappointing</option><option value="quick">Feed me now</option><option value="cheap">Skint mode</option><option value="protein">Protein, obviously</option></select></div></div><RecipeGrid rs={visible} favourites={favourites} toggleFav={toggleFav} open={r=>{setSelected(r);setServings(4)}}/></section></>}
 {view==="fridge"&&<section className="workspace"><Title icon={<Refrigerator/>} tag="USE IT OR LOSE IT" title="What’s in your fridge?" text="Type what you’ve got. We’ll find dinners before it turns furry."/><label className="search big"><Search/><input value={fridge} onChange={e=>setFridge(e.target.value)} placeholder="e.g. chicken, peppers, rice"/><kbd>{visible.length} matches</kbd></label><CategoryBar cat={cat} setCat={setCat}/><RecipeGrid rs={visible.slice(0,24)} favourites={favourites} toggleFav={toggleFav} open={setSelected}/></section>}
 {view==="favourites"&&<section className="workspace"><Title icon={<Heart/>} tag="THE ONES WORTH REPEATING" title="Your favourites" text="Everything you saved, all in one place. Sensible for once."/>{favourites.length?<RecipeGrid rs={recipes.filter(r=>favourites.includes(r.id))} favourites={favourites} toggleFav={toggleFav} open={setSelected}/>:<div className="empty favourites-empty"><span>♡</span><h3>You haven’t saved a bloody thing.</h3><p>Tap the heart on a recipe and it’ll live here.</p></div>}</section>}
 {view==="planner"&&<Planner planner={planner} addPlan={addPlan} setPlanner={setPlanner} open={setSelected}/>} {view==="shopping"&&<Shopping shopping={visibleShopping} checked={checked} setChecked={setChecked} clear={()=>{setRemoved(shopping.map(([item])=>item));setChecked([])}} remove={item=>{setRemoved(v=>v.includes(item)?v:[...v,item]);setChecked(v=>v.filter(x=>x!==item))}}/>}</>}
 {showTop&&<button className="back-to-top" onClick={()=>window.scrollTo({top:0,behavior:"smooth"})} aria-label="Back to top"><ArrowUp/>Top</button>}<footer><span>GRIMRECIPES</span><p>Real Food. Bad Attitude. No life stories before the ingredients.</p></footer></main>
}
function Title({icon,tag,title,text}:{icon:React.ReactNode;tag:string;title:string;text:string}){return <div className="workspace-title">{icon}<div><span className="eyebrow">{tag}</span><h1>{title}</h1><p>{text}</p></div></div>}
function CategoryBar({cat,setCat}:{cat:string;setCat:(s:string)=>void}){return <div className="categories">{categories.map(c=><button key={c} className={cat===c?"active":""} onClick={()=>setCat(c)}>{c}</button>)}</div>}
function RecipeGrid({rs,favourites,toggleFav,open}:{rs:Recipe[];favourites:number[];toggleFav:(id:number)=>void;open:(r:Recipe)=>void}){return rs.length?<div className="recipe-grid">{rs.map((r,i)=><article className="recipe-card" key={r.id} onClick={()=>open(r)}><div className={`food-art tone-${r.id%6}`}>{r.image?<img src={r.image} alt={`${r.name}, cooked and ready to serve`}/>:<span aria-hidden="true">{r.emoji}</span>}<b>{r.category}</b>{i<3&&<i>GRIM PICK</i>}<button aria-label="Favourite" onClick={e=>{e.stopPropagation();toggleFav(r.id)}}><Heart fill={favourites.includes(r.id)?"currentColor":"none"}/></button></div><div className="card-body"><h3>{r.name}</h3><p>{r.blurb}</p><div className="meta"><span><Clock3/>{r.time}m</span><span><PoundSterling/>£{r.cost.toFixed(2)}/serve</span><span><Dumbbell/>{r.protein}g</span></div><div className="score"><span>GRIM SCORE</span><b>{r.score}</b><i style={{"--score":`${r.score*10}%`}as React.CSSProperties}/></div></div></article>)}</div>:<div className="empty"><span>🫠</span><h3>Nothing. Absolutely nothing.</h3><p>Try fewer filters before blaming the recipes.</p></div>}
function RecipeDetail({recipe:r,servings,setServings,onBack,favourite,toggleFav,addPlan}:{recipe:Recipe;servings:number;setServings:(n:number)=>void;onBack:()=>void;favourite:boolean;toggleFav:(id:number)=>void;addPlan:(d:string,id:number)=>boolean}){const[day,setDay]=useState("Mon");const[addedDay,setAddedDay]=useState<string|null>(null);const factor=servings/4;const add=()=>{if(addPlan(day,r.id))setAddedDay(day)};return <section className="detail"><button className="back" onClick={onBack}><ArrowLeft/>Back — I’ve changed my mind</button><div className="detail-hero"><div className={`detail-art tone-${r.id%6}`}>{r.image?<img src={r.image} alt={`${r.name}, cooked and ready to serve`}/>:<span aria-hidden="true">{r.emoji}</span>}</div><div><span className="eyebrow">{r.category} · GRIM SCORE {r.score}</span><h1>{r.name}</h1><p className="recipe-description">{r.blurb}</p><div className="grim-verdict"><b>THE GRIM VERDICT</b><p>{r.verdict||r.blurb}</p></div><div className="detail-meta"><span><Clock3/>{r.time} mins</span><span><PoundSterling/>£{r.cost.toFixed(2)} / serving</span><span><Dumbbell/>{r.protein}g protein</span><span><Flame/>{r.calories} kcal</span></div><div className="detail-actions"><button className="primary" onClick={()=>toggleFav(r.id)}><Heart fill={favourite?"currentColor":"none"}/>{favourite?"Remove from favourites":"Add to favourites"}</button><select value={day} onChange={e=>{setDay(e.target.value);setAddedDay(null)}}>{days.map(d=><option key={d}>{d}</option>)}</select><button className={addedDay===day?"plan-added":""} onClick={add}>{addedDay===day?<><Check/>Added to {day}</>:<><Plus/>Inflict on {day}</>}</button></div>{addedDay===day&&<p className="plan-confirmation" role="status"><Check/> {r.name} is on {day}. The planner actually did something.</p>}</div></div><div className="recipe-content"><div><div className="ingredients-head"><h2>Stuff you need</h2><div className="servings"><button onClick={()=>setServings(Math.max(1,servings-1))}><Minus/></button><b>Feed {servings}</b><button onClick={()=>setServings(servings+1)}><Plus/></button></div></div><ul className="ingredients">{r.ingredients.map((x,i)=><li key={i}><span/><p>{factor===1?x:(x.match(/^\d+/)?`${Math.round(parseInt(x)*factor)}${x.replace(/^\d+/,"")}`:x)}</p></li>)}</ul></div><div><h2>Do this. In this order.</h2><ol className="steps">{r.steps.map((x,i)=><li key={i}><b>{i+1}</b><p>{x}</p></li>)}</ol></div></div></section>}
function Planner({planner,setPlanner,addPlan,open}:{planner:Record<string,number[]>;setPlanner:(p:Record<string,number[]>)=>void;addPlan:(d:string,id:number)=>boolean;open:(r:Recipe)=>void}){const remove=(d:string,i:number)=>setPlanner({...planner,[d]:(planner[d]||[]).filter((_,x)=>x!==i)});return <section className="workspace"><Title icon={<CalendarDays/>} tag="SEVEN DAYS. NO PANIC." title="Meal planner" text="Build the week, then let the shopping list do the boring bit."/><div className="week">{days.map(d=><div className="day" key={d}><h2>{d}<small>{(planner[d]||[]).length} meals</small></h2>{(planner[d]||[]).map((id,i)=>{const r=recipes.find(x=>x.id===id)!;return <div className="planned" key={`${id}-${i}`}><button onClick={()=>open(r)}><span>{r.emoji}</span><b>{r.name}</b><small>{r.time} min</small></button><button onClick={()=>remove(d,i)}><X/></button></div>})}{!(planner[d]||[]).length&&<p className="blank">No dinner. Bold strategy.</p>}<select value="" onChange={e=>{if(e.target.value)addPlan(d,Number(e.target.value));e.currentTarget.value=""}}><option value="">+ Add a recipe</option>{recipes.slice(0,40).map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></div>)}</div></section>}
function Shopping({shopping,checked,setChecked,clear,remove}:{shopping:[string,number][];checked:string[];setChecked:(x:string[])=>void;clear:()=>void;remove:(item:string)=>void}){const toggle=(x:string)=>setChecked(checked.includes(x)?checked.filter(i=>i!==x):[...checked,x]);return <section className="workspace narrow"><Title icon={<ShoppingBasket/>} tag="ONE LIST. LESS FAFF." title="Shopping list" text="Built automatically from your meal plan. Tick off cupboard staples without nuking your week."/>{shopping.length?<><div className="list-actions"><b>{shopping.length-checked.length} things left</b><button onClick={()=>setChecked([])}><RotateCcw/>Untick all</button><button className="danger" onClick={clear}><Trash2/>Clear basket</button></div><div className="shopping-list">{shopping.map(([item,count])=><div className={`shopping-item ${checked.includes(item)?"done":""}`} key={item}><button className="shopping-toggle" onClick={()=>toggle(item)}><span>{checked.includes(item)&&<Check/>}</span><p>{item}</p>{count>1&&<b>x{count}</b>}</button><button className="shopping-remove" aria-label={`Remove ${item}`} onClick={()=>remove(item)}><Trash2/></button></div>)}</div></>:<div className="empty"><span>🛒</span><h3>Your list is aggressively empty.</h3><p>Add meals to your week and the shopping list builds itself.</p></div>}</section>}
